#include "domain/life_stage_presentation.hpp"
#include "domain/needs.hpp"
#include <iostream>
using namespace stalthos;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){try{Lifecycle life(HeroSpecies::Smalltrotter);check(life.calendarAge()==0 && domain::lifeStageBulk(life.stage())==1,"ordinary startup preserved");life.restoreState(life.species(),2994,LifeStage::Juvenile);needs::NeedsCore needs(life.species());needs.restoreState(0,0,.8,0,true);SimCore clock;std::size_t transitions=0;for(int i=0;i<4;++i){auto dt=clock.advance(2,1);transitions+=life.advance(dt).size();needs.advance(dt);}check(life.stage()==LifeStage::Adult && transitions==1 && life.calendarAge()==3002,"actual one calendar threshold");check(domain::lifeStageBulk(life.stage())==1.25 && clock.physicalSeconds()==8 && clock.calendarSeconds()==8,"stage-derived bulk preserves clocks");check(std::abs(needs.fatigue()-.4)<1e-10,"physical recovery once across growth");life.restoreState(life.species(),2994,LifeStage::Juvenile);needs.restoreState(0,0,.8,0,true);TimeStep accelerated{2,100};life.advance(accelerated);needs.advance(accelerated);check(life.calendarAge()==3094 && std::abs(needs.fatigue()-.7)<1e-10,"calendar growth separated from physical recovery");domain::LifeStagePresentationTuning custom;custom.horizontalBulk[2]=1.1;check(domain::lifeStageBulk(LifeStage::Adult,custom)==1.1,"refinable presentation data");std::cout<<"LIFE_STAGE_OK actual threshold milestone stage bulk clock and physical needs separation\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
